CREATE TYPE compensation_state AS ENUM (\n  'OPEN','EVIDENCE_VALIDATED','NOTIFIED','PLAN_SELECTED',\n  'EXECUTING','RECOVERED','DISPUTED','WRITTEN_OFF','REVERSED'\n);\n\nCREATE TABLE compensation_case (\n  tenant_id            uuid NOT NULL,\n  compensation_case_id uuid NOT NULL,\n  payment_id           uuid NOT NULL,\n  invalidity_type      invalidity_type NOT NULL,\n  evidence_id          uuid NOT NULL,\n  subcontractor_id     uuid NOT NULL,\n  project_id           uuid NOT NULL,\n  amount_to_recover    numeric(18,2) NOT NULL,\n  status               compensation_state NOT NULL DEFAULT 'OPEN',\n  aggregate_version    bigint NOT NULL DEFAULT 1,\n  created_at           timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, compensation_case_id),\n  UNIQUE (tenant_id, payment_id, invalidity_type, evidence_id)\n);\n\nCREATE TABLE recovery_account (\n  tenant_id        uuid NOT NULL,\n  subcontractor_id uuid NOT NULL,\n  project_id       uuid NOT NULL,\n  saldo_pendiente  numeric(18,2) NOT NULL DEFAULT 0,\n  version          bigint NOT NULL DEFAULT 0,\n  PRIMARY KEY (tenant_id, subcontractor_id, project_id),\n  CHECK (saldo_pendiente >= 0)\n);\n\nCREATE TABLE deduction_log (\n  tenant_id        uuid NOT NULL,\n  deduction_id     uuid NOT NULL,\n  subcontractor_id uuid NOT NULL,\n  project_id       uuid NOT NULL,\n  amount           numeric(18,2) NOT NULL,\n  applied_at       timestamptz NOT NULL DEFAULT now(),\n  reversed         boolean NOT NULL DEFAULT false,\n  reversed_at      timestamptz,\n  PRIMARY KEY (tenant_id, deduction_id)\n);\n\nCREATE TYPE dispute_state AS ENUM (\n  'NOTICE_PREPARED','NOTICE_SENT','AWAITING_ACKNOWLEDGMENT','ACKNOWLEDGED',\n  'AWAITING_RESPONSE','NEGOTIATING','ESCALATED_TO_MEDIATION',\n  'ESCALATED_TO_ARBITRATION','RESOLVED_CONTRACTOR','RESOLVED_SUBCONTRACTOR',\n  'RESOLVED_PARTIAL','WITHDRAWN','LAPSED'\n);\nCREATE TYPE dispute_outcome AS ENUM (\n  'CONTRACTOR_WINS_TOTAL','CONTRACTOR_WINS_PARTIAL',\n  'SUBCONTRACTOR_WINS_TOTAL','SUBCONTRACTOR_WINS_PARTIAL',\n  'WITHDRAWN','LAPSED'\n);\n\nCREATE TABLE dispute_case (\n  tenant_id              uuid NOT NULL,\n  dispute_case_id        uuid NOT NULL,\n  compensation_case_id   uuid NOT NULL,\n  payment_id             uuid NOT NULL,\n  subcontractor_id       uuid NOT NULL,\n  project_id             uuid NOT NULL,\n  contract_id            uuid NOT NULL,\n  estado                 dispute_state NOT NULL,\n  version                bigint NOT NULL DEFAULT 1,\n  jurisdiction           varchar(40) NOT NULL,\n  contract_type          varchar(40) NOT NULL,\n  notice_sent_at         timestamptz,\n  acknowledgment_at      timestamptz,\n  response_deadline      date NOT NULL,\n  negotiation_deadline   date,\n  arbitration_deadline   date,\n  amount_claimed         numeric(18,2) NOT NULL,\n  amount_in_dispute      numeric(18,2) NOT NULL,\n  amount_recovered       numeric(18,2) NOT NULL DEFAULT 0,\n  interest_accrued       numeric(18,2) NOT NULL DEFAULT 0,\n  costs_allocated        numeric(18,2) NOT NULL DEFAULT 0,\n  outcome                dispute_outcome,\n  outcome_recorded_at    timestamptz,\n  outcome_evidence_id    uuid,\n  evidence_manifest_id   uuid NOT NULL,\n  evidence_manifest_hash varchar(64) NOT NULL,\n  created_at             timestamptz NOT NULL DEFAULT now(),\n  updated_at             timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, dispute_case_id),\n  UNIQUE (tenant_id, compensation_case_id)\n);\n\nCREATE TABLE business_calendar (\n  jurisdiction_id varchar(40) NOT NULL,\n  calendar_date   date NOT NULL,\n  is_business_day boolean NOT NULL,\n  holiday_name    varchar(120),\n  source          varchar(80) NOT NULL,\n  valid_from      timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (jurisdiction_id, calendar_date)\n);\n\nCREATE OR REPLACE FUNCTION add_business_days(p_jurisdiction varchar, p_start date, p_days int)\nRETURNS date LANGUAGE plpgsql STABLE AS $$\nDECLARE v date := p_start; v_added int := 0;\nBEGIN\n  WHILE NOT EXISTS (\n    SELECT 1 FROM business_calendar WHERE jurisdiction_id = p_jurisdiction\n      AND calendar_date = v AND is_business_day) LOOP\n    v := v + 1;\n  END LOOP;\n  WHILE v_added < p_days LOOP\n    v := v + 1;\n    IF EXISTS (SELECT 1 FROM business_calendar WHERE jurisdiction_id = p_jurisdiction\n               AND calendar_date = v AND is_business_day) THEN\n      v_added := v_added + 1;\n    END IF;\n  END LOOP;\n  RETURN v;\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION add_calendar_days(p_start date, p_days int)\nRETURNS date LANGUAGE sql IMMUTABLE AS $$ SELECT p_start + p_days; $$;\n\nCREATE TABLE legal_interest_rate (\n  jurisdiction_id  varchar(40) NOT NULL,\n  effective_from   date NOT NULL,\n  effective_to     date,\n  annual_rate      numeric(8,6) NOT NULL,\n  source_reference varchar(200) NOT NULL,\n  PRIMARY KEY (jurisdiction_id, effective_from)\n);\n\nCREATE TABLE evidence_manifest (\n  tenant_id        uuid NOT NULL,\n  manifest_id      uuid NOT NULL,\n  dispute_case_id  uuid NOT NULL,\n  manifest_version int NOT NULL DEFAULT 1,\n  canonical_json   jsonb NOT NULL,\n  hmac_sha256      varchar(88) NOT NULL,\n  signing_key_id   varchar(80) NOT NULL,\n  signed_at        timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, manifest_id)\n);\nCREATE TABLE evidence_manifest_document (\n  tenant_id     uuid NOT NULL,\n  manifest_id   uuid NOT NULL,\n  document_id   uuid NOT NULL,\n  document_type varchar(40) NOT NULL,\n  sha256        varchar(64) NOT NULL,\n  PRIMARY KEY (tenant_id, manifest_id, document_id)\n);\nCREATE TABLE evidence_manifest_chain_of_custody (\n  tenant_id   uuid NOT NULL,\n  access_id   bigserial PRIMARY KEY,\n  manifest_id uuid NOT NULL,\n  document_id uuid NOT NULL,\n  accessed_by uuid NOT NULL,\n  accessed_at timestamptz NOT NULL DEFAULT now(),\n  purpose     varchar(60) NOT NULL,\n  ip_address  inet\n);\n\nCREATE TABLE dispute_case_current (\n  tenant_id                    uuid NOT NULL,\n  dispute_case_id              uuid NOT NULL,\n  compensation_case_id         uuid NOT NULL,\n  payment_id                   uuid NOT NULL,\n  subcontractor_id             uuid NOT NULL,\n  project_id                   uuid NOT NULL,\n  contract_id                  uuid NOT NULL,\n  estado                       dispute_state NOT NULL,\n  phase_started_at             timestamptz NOT NULL,\n  outcome                      dispute_outcome,\n  outcome_recorded_at          timestamptz,\n  evidence_complete            boolean NOT NULL DEFAULT false,\n  manifest_hash                varchar(64) NOT NULL DEFAULT '',\n  last_evidence_access         timestamptz,\n  amount_in_dispute_contract   numeric(18,2) NOT NULL,\n  currency_code                char(3) NOT NULL DEFAULT 'USD',\n  amount_in_dispute_functional numeric(18,2) NOT NULL,\n  functional_fx_rate           numeric(12,6) NOT NULL DEFAULT 1,\n  functional_fx_rate_date      date NOT NULL DEFAULT CURRENT_DATE,\n  phase_deadline               date NOT NULL DEFAULT CURRENT_DATE,\n  days_in_phase                int NOT NULL DEFAULT 0,\n  business_days_remaining      int NOT NULL DEFAULT 0,\n  sla_status                   varchar(15) NOT NULL DEFAULT 'ON_TRACK',\n  next_action_type             varchar(40) NOT NULL DEFAULT 'NONE',\n  next_action_owner_role       varchar(40) NOT NULL DEFAULT 'LEGAL',\n  next_action_due_date         date,\n  deadline_consequence         text,\n  provision_functional         numeric(18,2) NOT NULL DEFAULT 0,\n  provision_contract           numeric(18,2) NOT NULL DEFAULT 0,\n  provision_dmn_version        varchar(20) NOT NULL DEFAULT 'v1',\n  provision_reason             varchar(200) NOT NULL DEFAULT '',\n  provision_as_of              date NOT NULL DEFAULT CURRENT_DATE,\n  version                      bigint NOT NULL DEFAULT 1,\n  created_at                   timestamptz NOT NULL DEFAULT now(),\n  updated_at                   timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, dispute_case_id),\n  UNIQUE (tenant_id, compensation_case_id)\n);\nCREATE INDEX idx_dc_priority ON dispute_case_current\n  (tenant_id, next_action_owner_role, next_action_due_date, sla_status);\n\nCREATE TABLE dispute_case_history (\n  tenant_id        uuid NOT NULL,\n  history_id       bigserial PRIMARY KEY,\n  dispute_case_id  uuid NOT NULL,\n  valid_from       timestamptz NOT NULL,\n  estado           dispute_state NOT NULL,\n  outcome          dispute_outcome,\n  amount_in_dispute_contract numeric(18,2) NOT NULL,\n  currency_code    char(3) NOT NULL,\n  provision_functional numeric(18,2),\n  version          bigint NOT NULL,\n  source_event_id  uuid NOT NULL,\n  source_event_type varchar(60) NOT NULL,\n  projection_version varchar(20) NOT NULL\n);\nCREATE VIEW dispute_case_history_intervals AS\nSELECT h.*, LEAD(h.valid_from) OVER (\n  PARTITION BY h.tenant_id, h.dispute_case_id ORDER BY h.valid_from) AS valid_to\nFROM dispute_case_history h;\n\nCREATE TABLE dispute_provision_snapshot (\n  tenant_id                  uuid NOT NULL,\n  snapshot_date              date NOT NULL,\n  dispute_case_id            uuid NOT NULL,\n  snapshot_seq               smallint NOT NULL DEFAULT 0,\n  is_adjustment              boolean NOT NULL DEFAULT false,\n  adjustment_reason          varchar(200),\n  project_id                 uuid NOT NULL,\n  subcontractor_id           uuid NOT NULL,\n  amount_in_dispute_contract numeric(18,2) NOT NULL,\n  currency_code              char(3) NOT NULL,\n  provision_contract         numeric(18,2) NOT NULL,\n  provision_functional       numeric(18,2) NOT NULL,\n  fx_rate                    numeric(12,6) NOT NULL,\n  fx_rate_date               date NOT NULL,\n  provision_dmn_version      varchar(20) NOT NULL,\n  provision_reason           varchar(200) NOT NULL,\n  prior_snapshot_date        date,\n  revaluation_gain_loss      numeric(18,2),\n  journal_entry_id           uuid,\n  PRIMARY KEY (tenant_id, snapshot_date, dispute_case_id, snapshot_seq)\n);\n\nCREATE TABLE dispute_phase_config (\n  contract_type varchar(40) NOT NULL,\n  jurisdiction  varchar(40) NOT NULL,\n  phase         varchar(30) NOT NULL,\n  time_unit     varchar(15) NOT NULL CHECK (time_unit IN ('CALENDAR_DAYS','BUSINESS_DAYS')),\n  duration      int NOT NULL CHECK (duration > 0),\n  PRIMARY KEY (contract_type, jurisdiction, phase)\n);\nINSERT INTO dispute_phase_config VALUES\n  ('FIDIC_RED_2017','*','NOTICE','CALENDAR_DAYS',28),\n  ('FIDIC_RED_2017','*','RESPONSE','CALENDAR_DAYS',14),\n  ('FIDIC_RED_2017','*','FULLY_DETAILED_CLAIM','CALENDAR_DAYS',84),\n  ('FIDIC_RED_2017','*','DETERMINATION','CALENDAR_DAYS',42),\n  ('FIDIC_RED_2017','*','DISSATISFACTION','CALENDAR_DAYS',28);\n\n-- Tablas de configuración global (sin tenant_id): NO llevan RLS por tenant\n-- business_calendar, legal_interest_rate, dispute_phase_config\n\nALTER TABLE compensation_case      ENABLE ROW LEVEL SECURITY;\nALTER TABLE recovery_account       ENABLE ROW LEVEL SECURITY;\nALTER TABLE deduction_log          ENABLE ROW LEVEL SECURITY;\nALTER TABLE dispute_case           ENABLE ROW LEVEL SECURITY;\nALTER TABLE evidence_manifest      ENABLE ROW LEVEL SECURITY;\nALTER TABLE evidence_manifest_document ENABLE ROW LEVEL SECURITY;\nALTER TABLE evidence_manifest_chain_of_custody ENABLE ROW LEVEL SECURITY;\nALTER TABLE dispute_case_current   ENABLE ROW LEVEL SECURITY;\nALTER TABLE dispute_case_history   ENABLE ROW LEVEL SECURITY;\nALTER TABLE dispute_provision_snapshot ENABLE ROW LEVEL SECURITY;\n\nDO $$\nDECLARE t text;\nBEGIN\n  FOR t IN SELECT unnest(ARRAY[\n    'compensation_case','recovery_account','deduction_log','dispute_case',\n    'evidence_manifest','evidence_manifest_document',\n    'evidence_manifest_chain_of_custody',\n    'dispute_case_current','dispute_case_history','dispute_provision_snapshot'\n  ]) LOOP\n    EXECUTE format('CREATE POLICY ti_%I ON %I USING (tenant_id = current_setting(''app.tenant_id'')::uuid)', t, t);\n  END LOOP;\nEND $$;